window.products.push({"id":1009352,"name":"Kaiser Bakeware Noblesse 9-Inch Round Springform Pan","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61AoAEvNTGL._AC_SL1500_.jpg","description":"This Kaiser Bakeware Noblesse round 9-inch non-stick springform pan features a heavy gauge steel for even and gentle heat distribution, and consistent browning. The double layer non-stick coating eliminates the need for flouring the pan, and allows for quick release and easy cleanup. Lifetime warranty on the springform buckle.","images":["https://m.media-amazon.com/images/I/61AoAEvNTGL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kaiser","source_asin":"B000P41PSC","category_path":"Home & Kitchen"},"sku":"BM-1009352","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000P41PSC","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000P41PSC","price_pending":true,"merchant_ready":false});
